import{b as e,O as d,g as r,j as a}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"性能测试基准","description":"","frontmatter":{},"headers":[],"relativePath":"performance/appendix/baseline/index.md","filePath":"性能测试/6.附录/性能测试基准.md","lastUpdated":1781755252000}'),s={name:"performance/appendix/baseline/index.md"};function n(o,t,l,h,i,g){return d(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="性能测试基准" tabindex="-1">性能测试基准 <a class="header-anchor" href="#性能测试基准" aria-label="Permalink to &quot;性能测试基准&quot;">​</a></h1><blockquote><p>搞清基本概念和指标，才知道测什么、怎么看、什么叫好。</p></blockquote><h2 id="核心指标" tabindex="-1">核心指标 <a class="header-anchor" href="#核心指标" aria-label="Permalink to &quot;核心指标&quot;">​</a></h2><p>先看全景，心里有数：</p><table tabindex="0"><thead><tr><th>指标</th><th>一句话含义</th><th>怎么衡量</th></tr></thead><tbody><tr><td><strong>响应时间</strong></td><td>请求从发出到收到响应要多久</td><td>P50/P95/P99，P95 比平均值重要</td></tr><tr><td><strong>吞吐量（TPS/QPS）</strong></td><td>系统每秒能处理多少个请求</td><td>在可接受的响应时间内能扛多少</td></tr><tr><td><strong>并发用户数</strong></td><td>同一时刻有多少人在操作</td><td>不等于在线人数，通常只有 10%~30%</td></tr><tr><td><strong>错误率</strong></td><td>请求失败的比例</td><td>压测期间必须接近 0%</td></tr><tr><td><strong>资源利用率</strong></td><td>服务器的 CPU/内存/磁盘/网络 吃掉了多少</td><td>各项 &lt; 80%，内存还要看是否只增不减</td></tr><tr><td><strong>LCP</strong></td><td>页面上主要内容&quot;出来&quot;的时间</td><td>≤ 2.5s</td></tr><tr><td><strong>INP</strong></td><td>用户交互后页面多久才响应</td><td>≤ 200ms</td></tr><tr><td><strong>CLS</strong></td><td>页面加载时内容&quot;跳&quot;了多远</td><td>≤ 0.1</td></tr></tbody></table><blockquote><p>前五个是<strong>后端视角</strong>（JMeter 压测盯这些），后三个是<strong>前端视角</strong>（Lighthouse 跑分盯这些）。两边都达标才算性能过关。</p></blockquote><h3 id="响应时间-response-time" tabindex="-1">响应时间 (Response Time) <a class="header-anchor" href="#响应时间-response-time" aria-label="Permalink to &quot;响应时间 (Response Time)&quot;">​</a></h3><p>用户从发出请求到收到完整响应所花的时间，是性能测试最重要的指标。</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>关注点</th></tr></thead><tbody><tr><td><strong>Average（平均值）</strong></td><td>所有请求响应时间的算术平均</td><td>容易被极端值拉偏，单独看意义不大</td></tr><tr><td><strong>Median / P50（中位数）</strong></td><td>50% 请求在此时间内完成</td><td>典型用户的真实体验</td></tr><tr><td><strong>P90</strong></td><td>90% 请求在此时间内完成</td><td>大多数用户的最差情况</td></tr><tr><td><strong>P95</strong></td><td>95% 请求在此时间内完成</td><td>尾延迟起点，这里开始要关注</td></tr><tr><td><strong>P99</strong></td><td>99% 请求在此时间内完成</td><td>极端情况，少数用户卡了多久</td></tr><tr><td><strong>Max（最大值）</strong></td><td>最慢的那次请求</td><td>有没有离谱的慢请求</td></tr><tr><td><strong>Std. Dev.（标准差）</strong></td><td>响应时间的离散程度</td><td>越大表示系统越不稳定，忽快忽慢</td></tr></tbody></table><blockquote><p><strong>P95/P99 比平均值更重要</strong>。平均值 300ms 看起来很漂亮，但 P99 如果是 5 秒，说明每 100 个用户就有 1 个卡了 5 秒。</p></blockquote><h3 id="吞吐量-throughput" tabindex="-1">吞吐量 (Throughput) <a class="header-anchor" href="#吞吐量-throughput" aria-label="Permalink to &quot;吞吐量 (Throughput)&quot;">​</a></h3><p>系统每秒能处理的请求数，衡量系统容量。根据请求类型不同，拆成两个常用概念：</p><table tabindex="0"><thead><tr><th>指标</th><th>全称</th><th>关注点</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>TPS</strong></td><td>Transactions Per Second</td><td>每秒完成的事务数，一次事务通常包含多个步骤</td><td>下单、支付、转账——涉及写操作</td></tr><tr><td><strong>QPS</strong></td><td>Queries Per Second</td><td>每秒处理的查询请求数，一个请求即是一次查询</td><td>搜索、查商品、读缓存——纯读操作</td></tr></tbody></table><blockquote><p>实际压测中经常混用，但记住<strong>写操作用 TPS，读操作用 QPS</strong>。同一个服务，查商品接口的 QPS 可能轻松跑到 2000，但下单接口的 TPS 可能只有 50——写操作天然比读操作重，涉及锁、事务、磁盘写入。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TPS = 并发用户数 ÷ 平均响应时间（秒）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：100 并发，平均响应 200ms（0.2s）</span></span>
<span class="line"><span>TPS = 100 ÷ 0.2 = 500</span></span></code></pre></div><table tabindex="0"><thead><tr><th>吞吐量趋势</th><th>说明</th></tr></thead><tbody><tr><td>随并发线性增长</td><td>系统还有余力</td></tr><tr><td>增速放缓</td><td>接近性能瓶颈</td></tr><tr><td>不再增长甚至下降</td><td>已达容量上限</td></tr><tr><td>吞吐量正常但错误率飙升</td><td>部分资源已耗尽</td></tr></tbody></table><blockquote><p>吞吐量不是越高越好——要在可接受的响应时间内谈。响应时间 5 秒的 1000 TPS 没有意义。</p></blockquote><h3 id="并发用户数-concurrent-users" tabindex="-1">并发用户数 (Concurrent Users) <a class="header-anchor" href="#并发用户数-concurrent-users" aria-label="Permalink to &quot;并发用户数 (Concurrent Users)&quot;">​</a></h3><p>同一时刻与系统交互的用户数。注意区分两个概念：</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th></tr></thead><tbody><tr><td><strong>并发用户数</strong></td><td>同一时刻正在操作的用户</td></tr><tr><td><strong>在线用户数</strong></td><td>登录了但不一定在操作的用户</td></tr></tbody></table><blockquote><p>在线 10000 人不代表并发 10000 人。大多数用户在看页面、填表单，真正同时发请求的可能只有 10%~30%。</p></blockquote><h3 id="错误率-error-rate" tabindex="-1">错误率 (Error Rate) <a class="header-anchor" href="#错误率-error-rate" aria-label="Permalink to &quot;错误率 (Error Rate)&quot;">​</a></h3><p>失败请求占总请求的百分比。压测时错误率必须接近 0%。</p><table tabindex="0"><thead><tr><th style="text-align:center;">错误率</th><th>意味着</th></tr></thead><tbody><tr><td style="text-align:center;">0%</td><td>正常</td></tr><tr><td style="text-align:center;">&lt; 1%</td><td>少量异常，需要排查</td></tr><tr><td style="text-align:center;">1%~5%</td><td>系统已在过载边缘</td></tr><tr><td style="text-align:center;">&gt; 5%</td><td>系统已经崩了，停止压测</td></tr></tbody></table><h3 id="资源利用率" tabindex="-1">资源利用率 <a class="header-anchor" href="#资源利用率" aria-label="Permalink to &quot;资源利用率&quot;">​</a></h3><p>被测服务器的资源消耗情况：</p><table tabindex="0"><thead><tr><th>资源</th><th>关注指标</th><th style="text-align:center;">告警线</th></tr></thead><tbody><tr><td>CPU</td><td>使用率</td><td style="text-align:center;">&gt; 80%</td></tr><tr><td>内存</td><td>使用率 / 是否持续增长不释放</td><td style="text-align:center;">&gt; 80% 或只增不减</td></tr><tr><td>磁盘 I/O</td><td>读写速率 / IOPS</td><td style="text-align:center;">视磁盘规格</td></tr><tr><td>网络</td><td>带宽占用 / 连接数</td><td style="text-align:center;">视带宽上限</td></tr><tr><td>数据库</td><td>连接池使用率 / 慢查询数</td><td style="text-align:center;">连接池 &gt; 80%</td></tr></tbody></table><blockquote><p>JMeter 只管发请求和记录响应，<strong>服务器资源要另开监控</strong>（top / htop / Prometheus / 云厂商监控面板）。</p></blockquote><h3 id="前端性能指标" tabindex="-1">前端性能指标 <a class="header-anchor" href="#前端性能指标" aria-label="Permalink to &quot;前端性能指标&quot;">​</a></h3><p>后端再快，前端加载慢用户还是觉得慢。前端指标关注用户<strong>在浏览器里的真实体验</strong>。</p><h4 id="core-web-vitals-核心网页指标" tabindex="-1">Core Web Vitals（核心网页指标） <a class="header-anchor" href="#core-web-vitals-核心网页指标" aria-label="Permalink to &quot;Core Web Vitals（核心网页指标）&quot;">​</a></h4><p>Google 推出的三个核心指标，直接影响 SEO 排名和灯塔评分：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th style="text-align:center;">好</th><th style="text-align:center;">需优化</th><th style="text-align:center;">差</th></tr></thead><tbody><tr><td><strong>LCP</strong></td><td>最大内容绘制——用户感知到&quot;主要内容出来了&quot;的时间点</td><td style="text-align:center;">≤2.5s</td><td style="text-align:center;">≤4s</td><td style="text-align:center;">&gt;4s</td></tr><tr><td><strong>INP</strong></td><td>交互延迟——点击/输入/滑动后，浏览器<strong>多久才响应</strong></td><td style="text-align:center;">≤200ms</td><td style="text-align:center;">≤500ms</td><td style="text-align:center;">&gt;500ms</td></tr><tr><td><strong>CLS</strong></td><td>累积布局偏移——页面加载中内容&quot;跳来跳去&quot;的程度</td><td style="text-align:center;">≤0.1</td><td style="text-align:center;">≤0.25</td><td style="text-align:center;">&gt;0.25</td></tr></tbody></table><blockquote><p>INP 是 2024 年 3 月替代 FID（First Input Delay）的新指标。FID 只测<strong>第一次</strong>交互的延迟，INP 测的是<strong>整个会话中所有交互</strong>里接近最差的那几次，更能反映真实体验。</p></blockquote><p><strong>三个指标的口语化理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LCP → &quot;页面出来了没？&quot;</span></span>
<span class="line"><span>INP → &quot;点了有反应没？&quot;</span></span>
<span class="line"><span>CLS → &quot;内容乱跳了没？&quot;</span></span></code></pre></div><h4 id="加载阶段指标" tabindex="-1">加载阶段指标 <a class="header-anchor" href="#加载阶段指标" aria-label="Permalink to &quot;加载阶段指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th style="text-align:center;">参考目标</th></tr></thead><tbody><tr><td><strong>TTFB</strong></td><td>首字节时间——从浏览器发起请求到收到服务器第一个响应字节的总耗时（含 DNS、TCP、SSL、服务器处理）</td><td style="text-align:center;">&lt; 800ms</td></tr><tr><td><strong>FCP</strong></td><td>首次内容绘制——页面上第一个像素（文字/图片）出现</td><td style="text-align:center;">≤ 1.8s</td></tr><tr><td><strong>TBT</strong></td><td>主线程阻塞总时长——FCP 到 TTI 之间长任务（&gt;50ms）的累计阻塞时间</td><td style="text-align:center;">&lt; 200ms</td></tr><tr><td><strong>TTI</strong></td><td>可交互时间——页面看起来好了，<strong>也能用了</strong></td><td style="text-align:center;">≤ 3.8s</td></tr><tr><td><strong>SI</strong></td><td>速度指数——页面内容可视区域被填充的速度</td><td style="text-align:center;">≤ 3.4s</td></tr></tbody></table><h4 id="请求与加载指标" tabindex="-1">请求与加载指标 <a class="header-anchor" href="#请求与加载指标" aria-label="Permalink to &quot;请求与加载指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>请求总数</strong></td><td>页面加载发出的 HTTP 请求数（含 JS/CSS/图片/字体/API）</td></tr><tr><td><strong>总下载体积</strong></td><td>所有资源的传输字节数，影响弱网用户</td></tr><tr><td><strong>DOMContentLoaded</strong></td><td>HTML 解析完成、DOM 可操作的时间</td></tr><tr><td><strong>Load</strong></td><td>页面及所有资源（图片/CSS 等）完全加载的时间</td></tr><tr><td><strong>首屏时间</strong></td><td>业务自定义的上半屏内容可见时间，混合应用的常用指标</td></tr></tbody></table><blockquote><p>首屏时间没有统一标准定义，常见方案：记录首屏区域最后一张图片加载完成的时间戳，或通过 MutationObserver 监听首屏关键 DOM 的出现时机。</p></blockquote><h4 id="运行时指标" tabindex="-1">运行时指标 <a class="header-anchor" href="#运行时指标" aria-label="Permalink to &quot;运行时指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th style="text-align:center;">目标</th></tr></thead><tbody><tr><td><strong>FPS</strong></td><td>帧率，滚动和动画流畅度的直观反映</td><td style="text-align:center;">60fps</td></tr><tr><td><strong>Long Tasks</strong></td><td>执行超过 50ms 的 JS 任务，阻塞主线程的元凶</td><td style="text-align:center;">越少越好</td></tr><tr><td><strong>JS Heap Size</strong></td><td>堆内存大小，持续上升不回落 = 内存泄漏</td><td style="text-align:center;">稳定不涨</td></tr><tr><td><strong>DOM Nodes</strong></td><td>页面 DOM 节点总数，过多直接拖慢渲染和交互</td><td style="text-align:center;">&lt; 1500</td></tr></tbody></table><h4 id="测量工具" tabindex="-1">测量工具 <a class="header-anchor" href="#测量工具" aria-label="Permalink to &quot;测量工具&quot;">​</a></h4><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>何时用</th></tr></thead><tbody><tr><td><strong>Lighthouse</strong></td><td>综合审计：性能/可访问性/SEO/最佳实践，输出评分和优化建议</td><td>开发阶段快速排查</td></tr><tr><td><strong>Chrome Performance 面板</strong></td><td>录制运行时火焰图，分析帧率、长任务、重排重绘</td><td>排查卡顿</td></tr><tr><td><strong>Chrome Network 面板</strong></td><td>请求瀑布流：时序、排队、DNS、连接、下载各阶段</td><td>排查接口慢和资源阻塞</td></tr><tr><td><strong>PageSpeed Insights</strong></td><td>线上页面评分 + Google 真实用户数据（CrUX）</td><td>上线后持续监控</td></tr><tr><td><strong>Web Vitals 扩展</strong></td><td>浏览器插件，实时浮层显示当前页面的 Core Web Vitals</td><td>开发时随时看</td></tr></tbody></table><blockquote><p>后端用 JMeter 测接口，前端用 Lighthouse + Performance 面板测加载和交互。</p></blockquote><h2 id="性能验收标准" tabindex="-1">性能验收标准 <a class="header-anchor" href="#性能验收标准" aria-label="Permalink to &quot;性能验收标准&quot;">​</a></h2><p>一张表汇总前后端各项指标的及格线，拿来就能用：</p><h3 id="后端验收" tabindex="-1">后端验收 <a class="header-anchor" href="#后端验收" aria-label="Permalink to &quot;后端验收&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:center;">及格线</th><th>说明</th></tr></thead><tbody><tr><td>错误率</td><td style="text-align:center;"><strong>0%</strong></td><td>压测期间不允许有失败请求</td></tr><tr><td>P95 响应时间</td><td style="text-align:center;"><strong>&lt; 500ms</strong></td><td>95% 的用户在这个时间内拿到响应</td></tr><tr><td>P99 响应时间</td><td style="text-align:center;"><strong>&lt; 1000ms</strong></td><td>极端情况也不超过 1 秒</td></tr><tr><td>CPU 使用率</td><td style="text-align:center;"><strong>&lt; 80%</strong></td><td>留 20% 余量应对突发</td></tr><tr><td>内存使用率</td><td style="text-align:center;"><strong>&lt; 80%</strong></td><td>同时观察是否只增不减（泄漏）</td></tr><tr><td>数据库连接池</td><td style="text-align:center;"><strong>&lt; 80%</strong></td><td>满了新请求直接报错</td></tr></tbody></table><blockquote><p>不同业务容忍度不同：支付接口 P95 可能要求 &lt; 200ms，后台报表导出 P95 &lt; 3s 就能接受。上面是<strong>通用基准</strong>，实际值以需求模板为准。</p></blockquote><h3 id="前端验收" tabindex="-1">前端验收 <a class="header-anchor" href="#前端验收" aria-label="Permalink to &quot;前端验收&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:center;">及格线</th><th>对应测什么</th></tr></thead><tbody><tr><td><strong>LCP</strong></td><td style="text-align:center;"><strong>≤ 2.5s</strong></td><td>Lighthouse Performance 评分</td></tr><tr><td><strong>INP</strong></td><td style="text-align:center;"><strong>≤ 200ms</strong></td><td>Chrome Performance 面板看长任务</td></tr><tr><td><strong>CLS</strong></td><td style="text-align:center;"><strong>≤ 0.1</strong></td><td>Lighthouse 或 Web Vitals 扩展</td></tr><tr><td><strong>FCP</strong></td><td style="text-align:center;"><strong>≤ 1.8s</strong></td><td>Lighthouse / Performance 面板</td></tr><tr><td><strong>TTFB</strong></td><td style="text-align:center;"><strong>&lt; 800ms</strong></td><td>Network 面板看首字节</td></tr><tr><td><strong>TBT</strong></td><td style="text-align:center;"><strong>&lt; 200ms</strong></td><td>Lighthouse / Performance 面板</td></tr><tr><td><strong>Lighthouse 总分</strong></td><td style="text-align:center;"><strong>≥ 90</strong></td><td>Chrome DevTools → Lighthouse 面板</td></tr></tbody></table><h3 id="一句话判断" tabindex="-1">一句话判断 <a class="header-anchor" href="#一句话判断" aria-label="Permalink to &quot;一句话判断&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后端达标：P95 &lt; 500ms + 错误率 0% + 资源 &lt; 80%</span></span>
<span class="line"><span>前端达标：LCP ≤ 2.5s + INP ≤ 200ms + CLS ≤ 0.1</span></span>
<span class="line"><span>全部满足 → 性能过关，可以上线。</span></span></code></pre></div><h2 id="性能测试类型" tabindex="-1">性能测试类型 <a class="header-anchor" href="#性能测试类型" aria-label="Permalink to &quot;性能测试类型&quot;">​</a></h2><h3 id="基准测试-benchmark-test" tabindex="-1">基准测试 (Benchmark Test) <a class="header-anchor" href="#基准测试-benchmark-test" aria-label="Permalink to &quot;基准测试 (Benchmark Test)&quot;">​</a></h3><p><strong>目的</strong>：建立性能参照线。</p><ul><li>单用户、单接口，跑若干次取平均</li><li>得到&quot;这个接口最快能多快&quot;</li><li>后续每次压测都跟基准对比，劣化超过 20% 就要排查</li></ul><h3 id="负载测试-load-test" tabindex="-1">负载测试 (Load Test) <a class="header-anchor" href="#负载测试-load-test" aria-label="Permalink to &quot;负载测试 (Load Test)&quot;">​</a></h3><p><strong>目的</strong>：验证系统在预期用户量下是否正常。</p><ul><li>并发量 = 预期的正常高峰值</li><li>持续时间至少 10~30 分钟</li><li>要求：响应时间在目标内、错误率 0%</li></ul><h3 id="压力测试-stress-test" tabindex="-1">压力测试 (Stress Test) <a class="header-anchor" href="#压力测试-stress-test" aria-label="Permalink to &quot;压力测试 (Stress Test)&quot;">​</a></h3><p><strong>目的</strong>：找到系统的性能拐点和崩溃上限。</p><ul><li>从低并发开始，逐步增加</li><li>观察 TPS 拐点——拐点处就是系统的性能上限</li><li>继续加压到系统崩溃，记录极限容量</li></ul><h3 id="稳定性测试-endurance-soak-test" tabindex="-1">稳定性测试 (Endurance / Soak Test) <a class="header-anchor" href="#稳定性测试-endurance-soak-test" aria-label="Permalink to &quot;稳定性测试 (Endurance / Soak Test)&quot;">​</a></h3><p><strong>目的</strong>：暴露长时间运行才会出现的问题。</p><ul><li>并发量取正常负载的 70%~80%</li><li>持续时间至少 2 小时，推荐 8~24 小时</li><li>重点观察：内存是否只增不减、响应时间是否随时间恶化、日志文件是否撑爆磁盘</li></ul><h3 id="浪涌测试-spike-test" tabindex="-1">浪涌测试 (Spike Test) <a class="header-anchor" href="#浪涌测试-spike-test" aria-label="Permalink to &quot;浪涌测试 (Spike Test)&quot;">​</a></h3><p><strong>目的</strong>：模拟瞬时流量尖峰。</p><ul><li>在很短时间（几秒到几十秒）内将并发拉到极高值</li><li>观察系统是否能扛住冲击、尖峰过后是否能恢复正常</li><li>秒杀、抢票、大促活动上线前必须做</li></ul><h2 id="性能测试流程" tabindex="-1">性能测试流程 <a class="header-anchor" href="#性能测试流程" aria-label="Permalink to &quot;性能测试流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 需求分析   → 确定目标：并发多少人？响应多快？TPS 多少？</span></span>
<span class="line"><span>2. 脚本开发   → 用 JMeter 搭建压测脚本，调试通过</span></span>
<span class="line"><span>3. 基准测试   → 单用户跑，建立基线</span></span>
<span class="line"><span>4. 负载测试   → 预期用户量下跑，验证达标</span></span>
<span class="line"><span>5. 压力测试   → 逐步加压找拐点，记录容量上限</span></span>
<span class="line"><span>6. 分析调优   → 找到瓶颈，修改代码或配置</span></span>
<span class="line"><span>7. 回归验证   → 调优后重新压测，确认改善</span></span>
<span class="line"><span>8. 输出报告   → 汇总指标、趋势图、瓶颈分析和优化建议</span></span></code></pre></div><h2 id="常见性能瓶颈" tabindex="-1">常见性能瓶颈 <a class="header-anchor" href="#常见性能瓶颈" aria-label="Permalink to &quot;常见性能瓶颈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>典型问题</th></tr></thead><tbody><tr><td>应用层</td><td>线程池太小、连接池不够、锁竞争、算法复杂度高</td></tr><tr><td>数据库层</td><td>慢 SQL、缺少索引、连接数上限过低、锁表</td></tr><tr><td>中间件层</td><td>Redis 内存满、消息队列积压、Nginx 连接数上限</td></tr><tr><td>系统层</td><td>CPU 打满、内存不足频繁 GC、磁盘 I/O 瓶颈、网络带宽占满</td></tr></tbody></table><h2 id="性能需求模板" tabindex="-1">性能需求模板 <a class="header-anchor" href="#性能需求模板" aria-label="Permalink to &quot;性能需求模板&quot;">​</a></h2><p>拿到一个压测需求时，先把这个表填清楚，再动手写脚本：</p><table tabindex="0"><thead><tr><th>条目</th><th>示例</th></tr></thead><tbody><tr><td>目标接口</td><td>/api/products（商品列表）、/api/orders（创建订单）</td></tr><tr><td>业务比例</td><td>80% 查商品 + 20% 下单</td></tr><tr><td>目标并发</td><td>500</td></tr><tr><td>目标响应时间</td><td>P95 &lt; 500ms</td></tr><tr><td>目标 TPS</td><td>&gt; 800</td></tr><tr><td>允许错误率</td><td>0%</td></tr><tr><td>测试环境</td><td>生产环境配置 × 0.5 的缩减版</td></tr><tr><td>压测时长</td><td>负载 30 分钟 + 压力 10 分钟</td></tr><tr><td>前端验收</td><td>LCP ≤ 2.5s / INP ≤ 200ms / CLS ≤ 0.1 / Lighthouse ≥ 90</td></tr></tbody></table><blockquote><p>需求不明确就开跑等于盲测。先有目标，再动手。</p></blockquote>`,79)])])}const b=e(s,[["render",n]]);export{p as __pageData,b as default};
